/* envio.css */
.btn { background: #1a7f37; color: white; padding: 8px 16px; }

/* alerta.css */
.btn { background: #cf222e; color: white; padding: 8px 16px; }

/* en el HTML: <button id="envio" class="btn"> y <button id="alerta" class="btn"> */

/* HTML de entrada: <button class="p-4 bg-green-700 hover:bg-green-800">x</button> */
@layer theme, base, components, utilities;
@layer theme {
  :root, :host {
    --color-green-700: oklch(52.7% 0.154 150.069);
    --color-green-800: oklch(44.8% 0.119 151.328);
    --spacing: 0.25rem;
    /* ...variables de fuente... */
  }
}
@layer base { /* reset del navegador: unas 150 líneas */ }
@layer utilities {
  .bg-green-700 { background-color: var(--color-green-700); }
  .p-4 { padding: calc(var(--spacing) * 4); }
  @media (hover: hover) {
    .hover\:bg-green-800:hover { background-color: var(--color-green-800); }
  }
}
